UTF-8') ?>"><button class="btn btn-outline-danger btn-sm w-100" type="submit"><i class="bi bi-trash me-1"></i>Excluir</button></form></div></article></div><?php endforeach; ?></div><?php endif; ?>
</main></div></div><?php require dirname(__DIR__) . '/layouts/mobile-navigation.php'; ?>
<div class="modal fade" id="scan-modal" tabindex="-1"><div class="modal-dialog modal-xl modal-dialog-scrollable"><form id="scan-form" class="modal-content border-0 shadow" method="post" action="<?= Url::to('/scanner') ?>" enctype="multipart/form-data"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars((string) $csrfToken, ENT_QUOTES, 'UTF-8') ?>"><div class="modal-header border-0"><h2 class="modal-title fs-5">Nova digitalização</h2><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3 mb-4"><div class="col-md-6"><label class="form-label">Título</label><input name="titulo" class="form-control" required placeholder="Ex.: Anotações de cálculo"></div><div class="col-md-4"><label class="form-label">Disciplina</label><select name="disciplina_id" class="form-select"><option value="">Sem disciplina</option><?php foreach ($disciplines as $discipline): ?><option value="<?= htmlspecialchars((string) $discipline['id'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars((string) $discipline['nome'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">OCR</label><select name="idioma_ocr" class="form-select"><option value="por">PT</option><option value="eng">EN</option><option value="spa">ES</option></select></div></div><div class="row g-3"><div class="col-lg-7"><div class="border rounded-3 p-3 bg-light"><video id="camera-preview" class="w-100 rounded bg-dark" autoplay playsinline muted style="max-height:360px"></video><canvas id="capture-canvas" class="d-none"></canvas><div class="d-flex flex-wrap gap-2 mt-3"><button type="button" class="btn btn-outline-primary" id="open-camera"><i class="bi bi-camera-video me-1"></i>Abrir câmera</button><button type="button" class="btn btn-primary" id="capture-page" disabled><i class="bi bi-camera me-1"></i>Capturar página</button><label class="btn btn-light border mb-0"><i class="bi bi-images me-1"></i>Selecionar imagens<input id="image-files" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden></label></div><p class="small text-muted mb-0 mt-3">A câmera depende da permissão do navegador e de uma origem segura (localhost ou HTTPS).</p></div></div><div class="col-lg-5"><h3 class="h6 fw-bold">Páginas</h3><div id="captured-pages" class="d-flex flex-column gap-2"><p class="text-muted small mb-0" id="empty-pages">Nenhuma página adicionada.</p></div></div></div></div><div class="modal-footer border-0"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancelar</button><button type="submit" class="btn btn-primary" id="save-scan" disabled>Salvar digitalização</button></div></form></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const video=document.getElementById('camera-preview'),canvas=document.getElementById('capture-canvas'),pages=document.getElementById('captured-pages'),save=document.getElementById('save-scan'),capture=document.getElementById('capture-page');let stream;function add(file){const row=document.createElement('div');row.className='d-flex gap-2 align-items-center border rounded p-2 bg-white';const img=document.createElement('img');img.src=URL.createObjectURL(file);img.width=52;img.height=52;img.className='object-fit-cover rounded';const text=document.createElement('span');text.className='small flex-grow-1 text-truncate';text.textContent=file.name;const up=document.createElement('button');up.type='button';up.className='btn btn-sm btn-light';up.innerHTML='<i class="bi bi-arrow-up"></i>';up.onclick=()=>{if(row.previousElementSibling)pages.insertBefore(row,row.previousElementSibling)};const down=document.createElement('button');down.type='button';down.className='btn btn-sm btn-light';down.innerHTML='<i class="bi bi-arrow-down"></i>';down.onclick=()=>{if(row.nextElementSibling)pages.insertBefore(row.nextElementSibling,row)};const del=document.createElement('button');del.type='button';del.className='btn btn-sm btn-outline-danger';del.innerHTML='<i class="bi bi-trash"></i>';del.onclick=()=>{row.remove();save.disabled=!pages.querySelector('input')};const input=document.createElement('input');input.type='file';input.name='paginas[]';input.hidden=true;const dt=new DataTransfer();dt.items.add(file);input.files=dt.files;row.append(img,text,up,down,del,input);document.getElementById('empty-pages')?.remove();pages.append(row);save.disabled=false;}document.getElementById('open-camera').onclick=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=stream;capture.disabled=false;}catch(e){alert('Não foi possível abrir a câmera. Selecione imagens ou verifique a permissão do navegador.')}};capture.onclick=()=>{if(!video.videoWidth)return;canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(blob=>add(new File([blob],`captura-${Date.now()}.jpg`,{type:'image/jpeg'})),'image/jpeg',.92)};document.getElementById('image-files').onchange=e=>[...e.target.files].forEach(add);document.getElementById('scan-modal').addEventListener('hidden.bs.modal',()=>stream?.getTracks().forEach(t=>t.stop()));});</script>
